anchor="    // UX-10 (LEI brand, D39;"
add='''    // UX-11 added at the brand integration (2026-11-03): a hovered primary button keeps its accent fill and readable text. The shared
    // .ui-btn:hover rule painted panel3 under accent-ink text, which left "Back to …" washed out (seen in the enterprise 404 screenshot).
    { await vp.goto(base + '#/nowhere/at-all'); await vp.waitForSelector('[data-testid=not-found-home]'); await vp.hover('[data-testid=not-found-home]'); await vp.waitForTimeout(300);
      const hv = await vp.evaluate(() => { const b = document.querySelector('[data-testid=not-found-home]'); const cs = getComputedStyle(b); const probe = document.createElement('i'); probe.style.background = 'var(--accent)'; document.body.append(probe); const acc = getComputedStyle(probe).backgroundColor; probe.remove();
        const rgb = (c) => c.match(/[\\d.]+/g).slice(0, 3).map(Number); const lum = (c) => { const [r, g, b2] = rgb(c).map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }); return 0.2126 * r + 0.7152 * g + 0.0722 * b2; };
        const L1 = lum(cs.color), L2 = lum(cs.backgroundColor); return { bg: cs.backgroundColor, acc, ratio: Math.round(((Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05)) * 100) / 100, hovered: b.matches(':hover') }; });
      ok(`UX-11-${tag}`, `a hovered primary button keeps its accent fill and readable text (${SCHEME}): background = the accent, contrast ≥ 4.5:1`, hv.hovered && hv.bg === hv.acc && hv.ratio >= 4.5, JSON.stringify(hv)); }
'''
assert anchor in s; s=s.replace(anchor,add+anchor,1); open(p,'w').write(s)
print('ok')
